import { useFormRender, type UseFormRenderOptions } from "./useFormRender";
import type { FormRenderDefinition, FormRenderItem } from "./types";

export interface DefineFormOptions<T extends object> {
  items: FormRenderItem<T>[];
  /** Standard Schema（valibot v.object 输出直接兼容），映射到 TanStack validators.onSubmit */
  schema?: unknown;
  onSubmit?: (ctx: { value: T }) => void | Promise<void>;
  /** 其余 TanStack useForm 选项透传（如 onSubmitInvalid） */
  formOptions?: Record<string, unknown>;
}

/**
 * 聚合入口：单次调用完成「字段定义 + 类型约束 + 表单实例」。
 *
 * 返回 `{ items, form, resetToDefaults }`：
 * - `items` / `form` 传给 `<FormRender>`（支持 `:definition` 单 prop 或 `:form` + `:items` 拆分）；
 * - `form` 可直接 `reset()` / `validate()` / `handleSubmit()`；
 * - `resetToDefaults()` 重置到 `items.default`（搜索表单"重置"语义）。
 *
 * 须在组件 setup 中调用（TanStack useForm 约束）。
 */
export function defineForm<T extends object>(
  config: DefineFormOptions<T>,
): FormRenderDefinition<T> {
  return useFormRender<T>(config satisfies UseFormRenderOptions<T>);
}

export { default as FormRender } from "./FormRender.vue";
export { defineForm, type DefineFormOptions } from "./define-form";
export { useFormRender, type UseFormRenderOptions } from "./useFormRender";
export { widgetRenders } from "./widgets";
export {
  bindField,
  CHECKED,
  MODEL_VALUE,
  SLIDER,
  VALUE,
  type BindingSpec,
} from "./widgets/bind";
export type {
  CurrencyWidgetOptions,
  FormRenderDefinition,
  FormRenderFormApi,
  FormRenderItem,
  InputWidgetOptions,
  NumberWidgetOptions,
  PasswordWidgetOptions,
  PickerWidgetOptions,
  RadioGroupWidgetOptions,
  SelectWidgetOptions,
  SliderWidgetOptions,
  TextareaWidgetOptions,
  WidgetContext,
  WidgetItemOption,
  WidgetRenderReturn,
  WidgetRenders,
} from "./types";

import type { AnyFieldApi, FormApi, VueFormApi } from "@tanstack/vue-form";
import type { VNode } from "vue";
import type { SelectItemOption } from "@/components/select";

/**
 * useForm() 返回实例的宽松形态（与 form/context.ts 的 FormInstance 同款契约：
 * provide/inject 与跨组件边界会擦除泛型，any 化是项目既定约定）。
 */
/* prettier-ignore */
export type FormRenderFormApi =
  FormApi<any, any, any, any, any, any, any, any, any, any, any, any> &
  VueFormApi<any, any, any, any, any, any, any, any, any, any, any, any>;

/** 字段渲染上下文（widget 柯里化第二段的唯一参数） */
export interface WidgetContext<T extends object> {
  field: AnyFieldApi;
  item: FormRenderItem<T>;
  /** 当前全量表单值（响应式，来自 form.useSelector(s => s.values)；联动用） */
  values: T;
}

export type WidgetRenderReturn<T extends object> = (ctx: WidgetContext<T>) => VNode;

/** select/radioGroup 等选项的通用形态（字符串简写或 { label, value }） */
export type WidgetItemOption = string | SelectItemOption;

/** password widget 选项 */
export interface PasswordWidgetOptions {
  placeholder?: string;
  autoComplete?: "current-password" | "new-password";
}

/** number widget 选项（对应 NumberInput props） */
export interface NumberWidgetOptions {
  min?: number;
  max?: number;
  step?: number;
  formatOptions?: Intl.NumberFormatOptions;
}

/** currency widget 选项（对应 CurrencyInput props） */
export interface CurrencyWidgetOptions {
  labelUnit?: string;
  valueUnit?: string;
  placeholder?: string;
}

/** textarea widget 选项（placeholder/rows 为原生 attr 透传） */
export interface TextareaWidgetOptions {
  placeholder?: string;
  rows?: number;
}

/** select widget 选项 */
export interface SelectWidgetOptions {
  options: WidgetItemOption[];
  placeholder?: string;
}

/** radioGroup widget 选项 */
export interface RadioGroupWidgetOptions {
  options: WidgetItemOption[];
  orientation?: "horizontal" | "vertical";
}

/** slider widget 选项 */
export interface SliderWidgetOptions {
  min?: number;
  max?: number;
  step?: number;
}

/** 日期类 widget 选项（DatePicker/DateRangePicker 同款 placeholder prop） */
export interface PickerWidgetOptions {
  placeholder?: string;
}

/**
 * widget 注册表类型契约：实现对象在 widgets/index.ts。
 * 类型集中于此避免循环依赖（type-only import 无运行时环）。
 */
export interface WidgetRenders<T extends object> {
  input(o?: InputWidgetOptions): WidgetRenderReturn<T>;
  password(o?: PasswordWidgetOptions): WidgetRenderReturn<T>;
  number(o?: NumberWidgetOptions): WidgetRenderReturn<T>;
  currency(o?: CurrencyWidgetOptions): WidgetRenderReturn<T>;
  textarea(o?: TextareaWidgetOptions): WidgetRenderReturn<T>;
  select(o: SelectWidgetOptions): WidgetRenderReturn<T>;
  checkbox(o?: { disabled?: boolean }): WidgetRenderReturn<T>;
  switch(o?: { disabled?: boolean }): WidgetRenderReturn<T>;
  radioGroup(o: RadioGroupWidgetOptions): WidgetRenderReturn<T>;
  slider(o?: SliderWidgetOptions): WidgetRenderReturn<T>;
  datePicker(o?: PickerWidgetOptions): WidgetRenderReturn<T>;
  monthPicker(o?: PickerWidgetOptions): WidgetRenderReturn<T>;
  yearPicker(o?: PickerWidgetOptions): WidgetRenderReturn<T>;
  dateRangePicker(o?: PickerWidgetOptions): WidgetRenderReturn<T>;
  /** 逃逸口：完全自定义渲染 */
  render(fn: (ctx: WidgetContext<T>) => VNode): WidgetRenderReturn<T>;
}

export interface FormRenderItem<T extends object> {
  /**
   * 字段名：严格 keyof T —— 自动补全 + 拼错编译报错。
   * 额外字段请在 T 中显式声明；运行时以 String(key) 归一为 FormField 的 name。
   */
  key: keyof T;
  title: string;
  description?: string;
  placeholder?: string;
  /**
   * 默认值（值或同步工厂）；defineForm 据此派生 defaultValues。
   * 类型为 T 值域联合 T[keyof T]（无 per-item 精确联动，强于 x-render 的 any）。
   */
  default?: T[keyof T] | (() => T[keyof T]);
  /** 栅格跨度：数字 = 占 n 列（须 ≤ 实际列数）；"full" = 整行 */
  span?: number | "full";
  /** 联动显隐；消费 FormRender 经 useSelector 建立的响应式 values */
  visible?: boolean | ((values: T) => boolean);
  hideLabel?: boolean;
  class?: string;
  /** TanStack 字段级校验器透传（如 onChangeAsync） */
  validators?: Record<string, unknown>;
  /** widget 描述；缺省 = r.input() */
  render?: (r: WidgetRenders<T>) => WidgetRenderReturn<T>;
  /** 逃逸口：原样合并到控件 vnode 的 props */
  componentProps?: Record<string, unknown>;
}

/** input widget 选项 */
export interface InputWidgetOptions {
  placeholder?: string;
  /** 原生 input type（text/email/search 等） */
  type?: string;
}

export interface FormRenderDefinition<T extends object> {
  items: FormRenderItem<T>[];
  form: FormRenderFormApi;
  /** 重置到 items.default（搜索表单"重置"语义） */
  resetToDefaults: () => void;
}

import { useForm } from "@tanstack/vue-form";
import type { FormRenderDefinition, FormRenderItem } from "./types";

export interface UseFormRenderOptions<T extends object> {
  items: FormRenderItem<T>[];
  /** Standard Schema（valibot v.object 输出直接兼容），映射到 TanStack validators.onSubmit */
  schema?: unknown;
  onSubmit?: (ctx: { value: T }) => void | Promise<void>;
  /** 其余 TanStack useForm 选项透传（如 onSubmitInvalid） */
  formOptions?: Record<string, unknown>;
}

/**
 * 底层原语：包装 TanStack useForm（聚合入口 defineForm 内部也走这里）。
 *
 * - `defaultValues` 从 `items[].default` 派生（值或同步工厂，缺省 null）——单一真相源；
 * - 显式泛型 `useForm<T>`，保住 onSubmit `{ value: T }` 全链路推断；
 * - 须在组件 setup 中调用（TanStack useForm 内部 `onMounted(formApi.mount)`）。
 */
export function useFormRender<T extends object>(
  options: UseFormRenderOptions<T>,
): FormRenderDefinition<T> {
  const { items, schema, onSubmit, formOptions } = options;

  const defaultValues = Object.fromEntries(
    items.map((item) => [
      String(item.key),
      typeof item.default === "function"
        ? (item.default as () => unknown)()
        : (item.default ?? null),
    ]),
  ) as T;

  // useForm 有 12 个必选泛型参数（validator 通道），validators 走 any 化宽松契约（同 context.ts FormInstance）
  const form = useForm<T, any, any, any, any, any, any, any, any, any, any, any>({
    defaultValues,
    // TanStack 默认在提交失败后 canSubmit=false 且 handleSubmit 被门控静默拦截，
    // 用户修正字段值后将永远无法再次提交（搜索表单致命）。
    // 放开门控：每次点击都执行完整校验流，失败走错误分发，成功才走 onSubmit。
    canSubmitWhenInvalid: true,
    ...(schema ? { validators: { onSubmit: schema } } : {}),
    ...(onSubmit ? { onSubmit: ({ value }) => onSubmit({ value }) } : {}),
    ...formOptions,
  });

  return { items, form, resetToDefaults: () => form.reset() };
}

import type { AnyFieldApi } from "@tanstack/vue-form";

/**
 * 值绑定形态描述：
 * - modelValue：大多数组件（Input/Password/Number/Currency/Textarea/picker 系/Select）
 * - checked：Checkbox/Switch
 * - value：RadioGroup
 * - SLIDER：Slider 特例 —— 值 prop 为 `value`，事件却是 `update:modelValue`，且数组语义（number ↔ [number]）
 */
export interface BindingSpec {
  prop: string;
  event: string;
  /** field 值 → 控件 prop 的转换（slider: number → [number]） */
  toProp?: (value: unknown) => unknown;
  /** 控件事件 → field 值的转换（slider: [number] → number） */
  fromEvent?: (value: unknown) => unknown;
}

export const MODEL_VALUE: BindingSpec = { prop: "modelValue", event: "modelValue" };
export const CHECKED: BindingSpec = { prop: "checked", event: "checked" };
export const VALUE: BindingSpec = { prop: "value", event: "value" };
export const SLIDER: BindingSpec = {
  prop: "value",
  event: "modelValue",
  toProp: (v) => (v === null || v === undefined ? undefined : [v]),
  fromEvent: (v) => (Array.isArray(v) ? (v[0] ?? null) : v),
};

/**
 * TanStack field → 控件 props 的统一绑定：
 * 值回显（field.state.value）+ 写回（handleChange）+ 失焦（handleBlur）。
 */
export function bindField(field: AnyFieldApi, spec: BindingSpec) {
  return {
    [spec.prop]: spec.toProp ? spec.toProp(field.state.value) : field.state.value,
    [`onUpdate:${spec.event}`]: (value: unknown) =>
      field.handleChange((spec.fromEvent ? spec.fromEvent(value) : value) as never),
    onBlur: field.handleBlur,
  };
}

import { h } from "vue";
import { Checkbox } from "@/components/checkbox";
import { Switch } from "@/components/switch";
import type { WidgetRenderReturn } from "../types";
import { CHECKED, bindField } from "./bind";

/**
 * checkbox/switch widget：boolean 形态（值 prop 为 checked，非 modelValue）。
 * 单行布局倾向 hideLabel + label 经 item.title 展示由使用者决定。
 */
export function renderCheckboxItem<T extends object>(
  options: { disabled?: boolean } = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(Checkbox, {
      disabled: options.disabled,
      ...bindField(ctx.field, CHECKED),
      ...ctx.item.componentProps,
    });
}

export function renderSwitchItem<T extends object>(
  options: { disabled?: boolean } = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(Switch, {
      disabled: options.disabled,
      ...bindField(ctx.field, CHECKED),
      ...ctx.item.componentProps,
    });
}

import type { WidgetRenders } from "../types";
import { renderCheckboxItem, renderSwitchItem } from "./boolean";
import {
  renderCurrencyItem,
  renderDatePickerItem,
  renderDateRangePickerItem,
  renderMonthPickerItem,
  renderNumberItem,
  renderPasswordItem,
  renderTextareaItem,
  renderYearPickerItem,
} from "./model-value";
import { renderInputItem } from "./input";
import { renderSelectItem } from "./select";
import { renderRadioGroupItem, renderSliderItem } from "./value";

/**
 * widget 注册表：`r.input({...})` 等柯里化工厂的运行时对象。
 * 文件按绑定形态聚合：input / model-value（modelValue 系）/ boolean（checked 系）/
 * value（radioGroup/slider）/ select（多子组件组装）。
 */
export function widgetRenders<T extends object>(): WidgetRenders<T> {
  return {
    input: renderInputItem<T>,
    password: renderPasswordItem<T>,
    number: renderNumberItem<T>,
    currency: renderCurrencyItem<T>,
    textarea: renderTextareaItem<T>,
    select: renderSelectItem<T>,
    checkbox: renderCheckboxItem<T>,
    switch: renderSwitchItem<T>,
    radioGroup: renderRadioGroupItem<T>,
    slider: renderSliderItem<T>,
    datePicker: renderDatePickerItem<T>,
    monthPicker: renderMonthPickerItem<T>,
    yearPicker: renderYearPickerItem<T>,
    dateRangePicker: renderDateRangePickerItem<T>,
    render: (fn) => fn,
  };
}

import { h } from "vue";
import { Input } from "@/components/input";
import type { InputWidgetOptions, WidgetRenderReturn } from "../types";
import { MODEL_VALUE, bindField } from "./bind";

/** input widget：单行文本输入（placeholder 为原生 attr 透传，aria-invalid 由 FormControl 接线） */
export function renderInputItem<T extends object>(
  options: InputWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(Input, {
      placeholder: options.placeholder,
      type: options.type,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

import { h } from "vue";
import { CurrencyInput } from "@/components/currency-input";
import { DatePicker } from "@/components/date-picker";
import { DateRangePicker } from "@/components/date-range-picker";
import { MonthPicker } from "@/components/month-picker";
import { NumberInput } from "@/components/number-input";
import { PasswordInput } from "@/components/password-input";
import { Textarea } from "@/components/textarea";
import { YearPicker } from "@/components/year-picker";
import type {
  CurrencyWidgetOptions,
  NumberWidgetOptions,
  PasswordWidgetOptions,
  PickerWidgetOptions,
  TextareaWidgetOptions,
  WidgetRenderReturn,
} from "../types";
import { MODEL_VALUE, bindField } from "./bind";

/** password widget：密码输入（autoComplete 对应原生 autocomplete） */
export function renderPasswordItem<T extends object>(
  options: PasswordWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(PasswordInput, {
      placeholder: options.placeholder,
      autoComplete: options.autoComplete,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

/** number widget：数值输入（modelValue: number|null） */
export function renderNumberItem<T extends object>(
  options: NumberWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(NumberInput, {
      min: options.min,
      max: options.max,
      step: options.step,
      formatOptions: options.formatOptions,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

/** currency widget：金额输入（labelUnit/valueUnit 单位展示） */
export function renderCurrencyItem<T extends object>(
  options: CurrencyWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(CurrencyInput, {
      labelUnit: options.labelUnit,
      valueUnit: options.valueUnit,
      placeholder: options.placeholder,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

/** textarea widget：多行文本（placeholder/rows 为原生 attr 透传） */
export function renderTextareaItem<T extends object>(
  options: TextareaWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(Textarea, {
      placeholder: options.placeholder,
      rows: options.rows,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

/** 日期类 widget 共用工厂（DatePicker/MonthPicker/YearPicker 同为 string|null 形态） */
function pickerRenderer<T extends object>(
  component: Parameters<typeof h>[0],
  options: PickerWidgetOptions,
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(component, {
      placeholder: options.placeholder,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

export function renderDatePickerItem<T extends object>(
  options: PickerWidgetOptions = {},
): WidgetRenderReturn<T> {
  return pickerRenderer<T>(DatePicker, options);
}

export function renderMonthPickerItem<T extends object>(
  options: PickerWidgetOptions = {},
): WidgetRenderReturn<T> {
  return pickerRenderer<T>(MonthPicker, options);
}

export function renderYearPickerItem<T extends object>(
  options: PickerWidgetOptions = {},
): WidgetRenderReturn<T> {
  return pickerRenderer<T>(YearPicker, options);
}

/** dateRangePicker widget：[start, end] | null 形态 */
export function renderDateRangePickerItem<T extends object>(
  options: PickerWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(DateRangePicker, {
      placeholder: options.placeholder,
      ...bindField(ctx.field, MODEL_VALUE),
      ...ctx.item.componentProps,
    });
}

import { h } from "vue";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValueText,
} from "@/components/select";
import { normalizeSelectItem } from "@/components/select/types";
import type { SelectWidgetOptions, WidgetRenderReturn } from "../types";
import { MODEL_VALUE, bindField } from "./bind";

/**
 * select widget：多子组件组装（Root + Trigger(ValueText) + Content(Items)）。
 * options 直接作为 Select 的 items（其内部做 string 归一化），Item 渲染 label。
 */
export function renderSelectItem<T extends object>(
  options: SelectWidgetOptions,
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(
      Select,
      {
        items: options.options,
        placeholder: options.placeholder,
        ...bindField(ctx.field, MODEL_VALUE),
        ...ctx.item.componentProps,
      },
      {
        default: () => [
          h(SelectTrigger, () => h(SelectValueText, { placeholder: options.placeholder })),
          h(SelectContent, () =>
            options.options.map((option) => {
              const normalized = normalizeSelectItem(option);
              return h(SelectItem, { key: normalized.value, item: normalized });
            }),
          ),
        ],
      },
    );
}

import { h } from "vue";
import { RadioGroup, RadioGroupItem } from "@/components/radio-group";
import { Slider } from "@/components/slider";
import { normalizeSelectItem } from "@/components/select/types";
import type { RadioGroupWidgetOptions, SliderWidgetOptions, WidgetRenderReturn } from "../types";
import { SLIDER, VALUE, bindField } from "./bind";

/** radioGroup widget：单选组（值 prop 为 value；options 映射 RadioGroupItem，label 为插槽文本） */
export function renderRadioGroupItem<T extends object>(
  options: RadioGroupWidgetOptions,
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(
      RadioGroup,
      {
        orientation: options.orientation,
        ...bindField(ctx.field, VALUE),
        ...ctx.item.componentProps,
      },
      {
        default: () =>
          options.options.map((option) => {
            const normalized = normalizeSelectItem(option);
            return h(
              RadioGroupItem,
              { key: normalized.value, value: normalized.value },
              { default: () => normalized.label },
            );
          }),
      },
    );
}

/**
 * slider widget：number ↔ number[] 混合绑定特例
 * （值 prop 为 `value`，事件却是 `update:modelValue` 且数组语义，由 SLIDER spec 转换）。
 */
export function renderSliderItem<T extends object>(
  options: SliderWidgetOptions = {},
): WidgetRenderReturn<T> {
  return (ctx) =>
    h(Slider, {
      min: options.min,
      max: options.max,
      step: options.step,
      ...bindField(ctx.field, SLIDER),
      ...ctx.item.componentProps,
    });
}
